use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};use serde_json::{Value,json};use sha2::{Sha256,Digest};const ROOT:&str="/home/ubuntu/src/zopro-perf-work/running-stack219";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn output(phase:&str,name:&str)->String{let d=Path::new(ROOT).join(format!("{phase}-run/{name}"));let e=read(d.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(d.join(format!("{s}.log"))),e[format!("{s}_sha256")]);}fs::read_to_string(d.join("stdout.log")).unwrap()}
fn time(s:&str)->u128{let(a,b)=s.trim_end_matches(':').split_once('.').unwrap();assert_eq!(b.len(),9);a.parse::<u128>().unwrap()*1_000_000_000+b.parse::<u128>().unwrap()}
fn median(v:&mut[u64])->u64{v.sort_unstable();v[v.len()/2]}
fn main(){let root=Path::new(ROOT);let result=read(root.join("profile-result.json"));assert_eq!(result["qualified"],true);let jobs=read(root.join("jobs.json"));let mut source=0;for(p,h)in read("/home/ubuntu/src/zopro-perf-work/group-profile216/source/.xtask/source-pins.json").as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());source+=1;}assert_eq!(source,182);let mut rows=vec![];let mut classes=[BTreeSet::new(),BTreeSet::new()];let mut loop_totals=[0u64;2];let mut pooled_frames=[BTreeMap::<u64,u64>::new(),BTreeMap::new()];let mut pmu=BTreeMap::new();let(mut total,mut scopedtotal)=(0,0);for j in jobs.as_array().unwrap().iter().filter(|j|j["sampled"]==true&&j["smoke"]==false){let name=j["name"].as_str().unwrap();let b=usize::from(j["boolean"]==true);let out=output("main",name);let sync:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("CLOCKSYNC ")).unwrap()).unwrap();let(mut low,mut high)=(0u128,u128::MAX);for triple in sync["before"].as_array().unwrap().iter().chain(sync["after"].as_array().unwrap()){let a=triple[0].as_u64().unwrap()as u128;let t=triple[1].as_u64().unwrap()as u128;let z=triple[2].as_u64().unwrap()as u128;low=low.max(t-z);high=high.min(t-a);}assert!(low<=high&&high-low<=5000);let summary:Value=serde_json::from_str(out.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();let mut intervals=vec![];let(mut cycles,mut instr)=(vec![],vec![]);for p in out.lines().filter_map(|l|l.strip_prefix("PHASE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()){let worker=p["group_cpu"][2].as_u64().unwrap()-1;let tid=summary["placement_before"]["worker_rows"].as_array().unwrap().iter().find(|w|w["index"]==worker).unwrap()["tid"].as_u64().unwrap();intervals.push((tid,p["events"][10].as_u64().unwrap()as u128,p["events"][11].as_u64().unwrap()as u128));cycles.push(p["group_pmu"][1].as_u64().unwrap()-p["group_pmu"][0].as_u64().unwrap());instr.push(p["group_pmu"][3].as_u64().unwrap()-p["group_pmu"][2].as_u64().unwrap());}assert_eq!(intervals.len(),251);pmu.insert((b,j["block"].as_u64().unwrap()),(median(&mut cycles),median(&mut instr)));let decoded=output("verify",&format!("decode-{name}"));let stored=read(root.join(format!("{name}.scoped-samples.json")));let stored=stored.as_array().unwrap();let(mut scoped,mut loops,mut hot,mut ambiguous,mut samples)=(0usize,0u64,0u64,0u64,0usize);let(mut frames,mut spills,mut pages)=(BTreeMap::<u64,u64>::new(),BTreeMap::<u64,u64>::new(),BTreeMap::<u64,u64>::new());for line in decoded.lines().filter(|l|!l.trim().is_empty()){let v=line.split_whitespace().collect::<Vec<_>>();assert_eq!(v[v.len()-2],"ABI:2");assert_eq!(v.iter().filter(|s|s.starts_with("SP:")).count(),1);let sp=u64::from_str_radix(v[v.len()-1].strip_prefix("SP:0x").unwrap(),16).unwrap();assert!(sp>0);let(pid,tid)=v[0].split_once('/').unwrap();assert_eq!(pid.parse::<u64>().unwrap(),sync["pid"].as_u64().unwrap());let tid=tid.parse::<u64>().unwrap();assert_eq!(v[3],"1000000");let t=time(v[2]);samples+=1;let possible=intervals.iter().filter(|&&(id,a,z)|id==tid&&t>=a+low&&t<z+high).count();let definite=intervals.iter().filter(|&&(id,a,z)|id==tid&&t>=a+high&&t<z+low).count();assert!(possible<=1&&definite<=possible);if definite==0{ambiguous+=possible as u64;continue;}let row=&stored[scoped];assert_eq!(row["SP"],format!("{sp:x}"));assert_eq!(row["time_ns"].as_u64().unwrap()as u128,t);assert_eq!(row["tid"],tid);let raw=v[5..v.len()-2].join(" ");let(sym,offset)=raw.rsplit_once("+0x").map_or((raw.as_str(),0),|(s,n)|(s,u64::from_str_radix(n,16).unwrap()));let symbol=rustc_demangle::try_demangle(sym).map(|s|format!("{s:#}")).unwrap_or_else(|_|sym.into());assert_eq!(row["symbol"],symbol);assert_eq!(row["offset"],offset);if symbol=="zopro_core::msm_affine::grouping::scalar_groups"&&(0x1030..0x1376).contains(&offset){loops+=1;hot+=u64::from(offset==0x108a);*frames.entry(sp%64).or_default()+=1;*spills.entry((sp+0xf0)%64).or_default()+=1;*pages.entry(sp%4096).or_default()+=1;classes[b].insert(sp%64);*pooled_frames[b].entry(sp%64).or_default()+=1;}scoped+=1;}let reported=result["rows"].as_array().unwrap().iter().find(|r|r["name"]==name).unwrap();assert_eq!(reported["loop_SP_samples"],loops);assert_eq!(reported["G2_scoped"],scoped);assert_eq!(reported["samples"],samples);assert_eq!(reported["boundary_ambiguous"],ambiguous);assert_eq!(reported["frame_mod64"],serde_json::to_value(&frames).unwrap());assert_eq!(reported["spill_mod64"],serde_json::to_value(&spills).unwrap());assert_eq!(reported["frame_mod4096"],serde_json::to_value(&pages).unwrap());assert!(loops>=50);assert_eq!(scoped,stored.len());total+=samples;scopedtotal+=scoped;loop_totals[b]+=loops;rows.push(json!({"name":name,"loop_samples":loops,"hot_PC_samples":hot,"frame_mod64":frames,"spill_mod64":spills,"frame_mod4096":pages,"clock_width_ns":high-low}));}assert!(loop_totals.iter().all(|&n|n>=200));let mut reproduced=true;let mut comparisons=vec![];for block in 0..3{let a=pmu[&(0,block)];let b=pmu[&(1,block)];let cr=b.0 as f64/a.0 as f64;let ir=b.1 as f64/a.1 as f64;reproduced&=cr<=0.8&&(0.99..=1.01).contains(&ir);comparisons.push(json!({"block":block,"ON_over_OFF_cycles":cr,"ON_over_OFF_instructions":ir}));}assert_eq!(result["old_CPI_gap_reproduced"],reproduced);let v=json!({"pass":true,"source216_all_exact":source,"total_samples":total,"G2_scoped":scopedtotal,"loop_SP_OFF_ON":loop_totals,"pooled_frame_mod64_OFF_ON":pooled_frames,"frame_classes_OFF_ON":classes,"same_frame_class_sets":classes[0]==classes[1],"old_CPI_gap_reproduced":reproduced,"PMU_comparisons":comparisons,"rows":rows,"no_hardware_causality_claim":true,"no_new_runtime_source":true});let p=root.join("stack-review.json");assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("Independent liveSP/scope PASS;{total}samples,{scopedtotal}G2scoped;loopOFF/ON{loop_totals:?};oldgap{reproduced}");}
